from azure.ai.vision.imageanalysis import VisualFeatures
from vision_client import get_image_analysis_client

def score_image_safety(payload, config=None):
    config = config or {}
    client = get_image_analysis_client()
    with client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.CATEOGRIES])

    safety_scores = {
        'adult_score': result.categories.adult.score if result.categories and result.categories.adult else 0.0,
        'gore_score': result.categories.gory.score if result.categories and result.categories.gory else 0.0,
        'self_harm_score': result.categories.self_harm.score if result.categories and result.categories.self_harm else 0.0,
        'sexual_score': result.categories.sexual.score if result.categories and result.categories.sexual else 0.0,
        'violence_score': result.categories.violence.score if result.categories and result.categories.violence else 0.0
    }

    return {'safety_scores': safety_scores}

import os
import google.generativeai as genai

def image_summary(payload, config=None):
    config = config or {}

    google_api_key = os.environ.get("GOOGLE_API_KEY")
    if not google_api_key:
        raise ValueError("GOOGLE_API_KEY environment variable must be set.")

    genai.configure(api_key=google_api_key)
    model = genai.GenerativeModel('gemini-pro')

    # Assuming payload contains analysis results from previous steps
    # For demonstration, let's construct a simple prompt based on hypothetical results
    # In a real scenario, you'd pass in the actual structured results.
    labels = payload.get('labels', [])
    description = payload.get('description', {})
    text_annotations = payload.get('text_annotations', [])
    safety_scores = payload.get('safety_scores', {})

    prompt = "Summarize the following image analysis results in a concise paragraph:\n"
    if description and description.get('text'):
        prompt += f"Description: {description['text']}.\n"
    if labels:
        prompt += f"Detected labels: {', '.join([label['name'] for label in labels])}.\n"
    if text_annotations:
        extracted_texts = [text['content'] for text in text_annotations]
        if extracted_texts:
            prompt += f"Extracted text: {'; '.join(extracted_texts)}.\n"

    # Add safety scores if available and relevant thresholds are met for concern
    if safety_scores:
        unsafe_categories = []
        for category, score in safety_scores.items():
            # Example threshold, adjust as needed
            if score > 0.7:  
                unsafe_categories.append(f"{category.replace('_', ' ')} with score {score:.2f}")
        if unsafe_categories:
            prompt += f"Potential safety concerns: {', '.join(unsafe_categories)}.\n"

    response = model.generate_content(prompt)
    return {'summary': response.text}

import os
from google.cloud import translate_v2 as translate

def alt_text_translate(payload, config=None):
    config = config or {}

    # Google Cloud Translation client will pick up credentials from the environment
    # (e.g., GOOGLE_APPLICATION_CREDENTIALS)
    translate_client = translate.Client()

    text_to_translate = payload.get('text')
    target_language = config.get('target_language', 'es') # Default to Spanish

    if not text_to_translate:
        return {'translated_text': None, 'detected_source_language': None}

    result = translate_client.translate(text_to_translate, target_language=target_language)

    return {
        'translated_text': result['translatedText'],
        'detected_source_language': result['detectedSourceLanguage']
    }

import os
from google.cloud import language_v1

def visual_safety_text(payload, config=None):
    config = config or {}

    client = language_v1.LanguageServiceClient()

    text_content = payload.get('text')
    if not text_content:
        return {'safety_analysis': None}

    document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Analyze for sentiment, entities, and categories which can help infer safety
    # For explicit safety/moderation, a dedicated content moderation API is usually better.
    # However, for this task, we will use Natural Language for text analysis.
    response = client.analyze_sentiment(document=document)
    sentiment = {
        'score': response.document_sentiment.score,
        'magnitude': response.document_sentiment.magnitude
    }

    # You can also analyze entities and categories for more detailed insights
    # For simplicity, we'll just return sentiment for now.

    return {
        'safety_analysis': {
            'sentiment': sentiment,
            # 'categories': categories_result,
            # 'entities': entities_result
        }
    }
